CREATE TABLE bracel_notifications(id uuid PRIMARY KEY,scope text NOT NULL,dedupe text NOT NULL,content jsonb NOT NULL,read_at timestamptz,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(scope,dedupe)); CREATE INDEX bracel_notifications_inbox ON bracel_notifications(scope,created_at,id); CREATE TABLE bracel_notification_preferences(scope text NOT NULL,channel text NOT NULL,enabled boolean NOT NULL,PRIMARY KEY(scope,channel)); CREATE TABLE bracel_mail_delivery(id uuid PRIMARY KEY,scope text NOT NULL,recipient text NOT NULL,sender text NOT NULL,subject text NOT NULL,body text NOT NULL,status text NOT NULL DEFAULT 'pending',accepted_at timestamptz); CREATE TABLE bracel_webhook_inbox(provider text NOT NULL,event_id text NOT NULL,payload jsonb NOT NULL,processed_at timestamptz,received_at timestamptz NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(provider,event_id));